// PRIDA 0.40 cumulative installer — FRONTIER TECH.
// Upload together with package.json to repository root. It never writes to GitHub or reads credentials.
import fs from 'node:fs';
import path from 'node:path';
import { gunzipSync } from 'node:zlib';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
const RELEASE='0.40';
const STATE='.prida-0.40';
const PAYLOAD_SHA256="8ba91698ba42a5178f4ad1c56f144be449edf3021e649f126ea8d4e8be6c8dbe";
const PAYLOAD_B64="";
const UNIT=["tests/architecture-029.test.mjs", "tests/doors-029.test.mjs", "tests/vehicle-030.test.mjs", "tests/asset-030.test.mjs", "tests/structures-030.test.mjs", "tests/vehicle-031.test.mjs", "tests/ram-flight-031.test.mjs", "tests/world-031.test.mjs", "tests/runway-0311.test.mjs", "tests/vehicle-0312.test.mjs", "tests/rockets-032.test.mjs", "tests/interiors-033.test.mjs", "tests/lifts-033.test.mjs", "tests/developer-ram-033.test.mjs", "tests/architecture-034.test.mjs", "tests/landscape-034.test.mjs", "tests/portal-035.test.mjs", "tests/portal-packaging-035.test.mjs", "tests/asset-bootstrap-0351.test.mjs", "tests/air-defence-036.test.mjs", "tests/performance-036.test.mjs", "tests/export-full-036.test.mjs", "tests/activity-037.test.mjs", "tests/armour-salvo-037.test.mjs", "tests/entity-delta-037.test.mjs", "tests/mobility-038.test.mjs", "tests/technology-040.test.mjs"];
const INTEGRATION=["tests/integration-030.test.mjs", "tests/integration-031.test.mjs", "tests/integration-contact-0312.test.mjs", "tests/integration-rockets-032.test.mjs", "tests/integration-world-031.test.mjs", "tests/integration-mobility-038.test.mjs", "tests/rapier-mobility-038.test.mjs"];
const root=path.dirname(fileURLToPath(import.meta.url));
const stateDir=path.join(root,STATE),stage=path.join(stateDir,'staging');
const ignored=new Set(['node_modules','dist','dist-crazygames','release',STATE,'.git']);
function die(message){throw new Error('[PRIDA '+RELEASE+'] '+message)}
function copyTree(from,to){
  fs.mkdirSync(to,{recursive:true});
  for(const e of fs.readdirSync(from,{withFileTypes:true})){
    if(ignored.has(e.name)||e.name.startsWith('.prida-0.'))continue;
    const a=path.join(from,e.name),b=path.join(to,e.name);
    if(e.isSymbolicLink())continue;
    if(e.isDirectory())copyTree(a,b);else if(e.isFile())fs.copyFileSync(a,b);
  }
}
function payload(){
  const raw=gunzipSync(Buffer.from(PAYLOAD_B64,'base64'));
  if(createHash('sha256').update(raw).digest('hex')!==PAYLOAD_SHA256)die('embedded source checksum failed');
  const o=JSON.parse(raw);if(!o['index.html']||!o['src/simulation.js']||!o['src/technology-system.js']||!o['tests/technology-040.test.mjs'])die('embedded source is incomplete');
  return o;
}
function apply(target,files){for(const [name,text] of Object.entries(files)){
  if(name.startsWith('/')||name.includes('\\')||name.split('/').some(x=>!x||x==='.'||x==='..'))die('unsafe path '+name);
  const file=path.join(target,name);fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,text);
}}
function run(args,label,env={}){
  const r=spawnSync(process.execPath,args,{cwd:stage,stdio:'inherit',env:{...process.env,...env}});
  if(r.status!==0)die(label+' failed ('+r.status+'). No source files were installed.');
}
function vite(out,env={}){
  const bin=path.join(root,'node_modules/vite/bin/vite.js');if(!fs.existsSync(bin))die('Vite is missing; run npm ci first.');
  run([bin,'build','--base','./','--outDir',out,'--emptyOutDir'],out+' Vite gate',env);
}
function commit(files){
  // All gates ran against staging. Copy only the embedded text snapshot; existing binary assets stay untouched.
  const temp=path.join(stateDir,'commit');fs.rmSync(temp,{recursive:true,force:true});fs.mkdirSync(temp,{recursive:true});apply(temp,files);
  for(const name of Object.keys(files)){const src=path.join(temp,name),dst=path.join(root,name);fs.mkdirSync(path.dirname(dst),{recursive:true});fs.copyFileSync(src,dst);}
}
export function install({checkOnly=false}={}){
  const files=payload();fs.rmSync(stateDir,{recursive:true,force:true});fs.mkdirSync(stateDir,{recursive:true});copyTree(root,stage);apply(stage,files);
  console.log('[PRIDA '+RELEASE+'] staged '+Object.keys(files).length+' text/source files; existing binary assets preserved.');
  run(['--test',...UNIT],'regression/unit gate');
  run(['--test',...INTEGRATION],'Rapier/Three/full Arena integration gate');
  vite('.bundle-check');
  vite('.portal-basic-check',{VITE_CG_PORTAL:'1',VITE_CG_ADS:'basic'});
  if(!checkOnly)commit(files);
  fs.rmSync(stateDir,{recursive:true,force:true});
  console.log('[PRIDA '+RELEASE+'] '+(checkOnly?'VERIFIED':'INSTALLED')+': construction, FPV, NOVA laboratory, vehicle modules, AEGIS, 0.38 mobility and prior fixes.');
  return true;
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  try{install({checkOnly:process.argv.includes('--check')})}catch(e){console.error(e.stack||e);process.exitCode=1;}
}
